class HeavyResource {
    int* data;
public:
    HeavyResource(HeavyResource&& other) noexcept
        : data(other.data) {
        // Resource ownership transfer: O(1)
        other.data = nullptr;
    }

    HeavyResource& operator=(HeavyResource&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            other.data = nullptr;
        }
        return *this;
    }
    // Avoids deep copy construction: O(N)
};

