// Reduce runtime computation costs (CPU cycles)
// Lookup Table replaces expensive computation with O(1) access.
static const float SIN_TABLE[360]; // Initialized at compile/load time

float fast_sin(int degrees) {
    return SIN_TABLE[degrees % 360];
}

