// Avoid Runtime Overhead (Virtual Dispatch)
// Zero-Cost Abstraction via templates/CRTP
struct Executor {
    void run() { /* implementation */ }
};

template <typename T>
void process_task(T& task) {
    // Static dispatch, compiler can inline/optimize heavily
    task.run();
}

